import anthropic

client = anthropic.Anthropic(max_retries=3, timeout=60.0)

try:
    message = client.messages.create(
        max_tokens=1024,
        messages=[{"role": "user", "content": "Hello, Claude"}],
        model="claude-opus-5-5",
    )
    print(message._request_id)
except anthropic.RateLimitError as e:
    # SDK already retried; honor retry-after or shed load
    print("429", e.response.headers.get("retry-after"))
except anthropic.APIConnectionError as e:
    print("network", e.__cause__)
except anthropic.APIStatusError as e:
    print(e.status_code, e.response.headers.get("request-id"))

